package org.apache.dubbo.common.utils;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Method;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.lang.reflect.TypeVariable;
import java.util.List;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.Future;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Tests for {@link ReflectUtils#getReturnTypes(Method)} focusing on the handling of
 * generic Future return types with TypeVariable arguments.
 */
public class ReflectUtilsTest {

    // Test interface with generic type variable
    public interface TypeClass<T> {
        CompletableFuture<T> getGenericFuture();
    }

    // Test interface with bounded type variable
    public interface BoundedTypeClass<T extends Number> {
        CompletableFuture<T> getBoundedGenericFuture();
    }

    // Test interface with non-generic Future return
    public interface NonGenericFutureClass {
        CompletableFuture<String> getNonGenericFuture();
    }

    // Test interface with raw Future return
    public interface RawFutureClass {
        Future getRawFuture();
    }

    // Test interface with non-Future return
    public interface NonFutureClass {
        String getNonFuture();
    }

    // Test interface with ParameterizedType in Future
    public interface ParameterizedFutureClass {
        CompletableFuture<List<String>> getParameterizedFuture();
    }

    @Test
    public void testGetReturnTypesWithGenericFutureTypeVariable() throws Exception {
        Method method = TypeClass.class.getMethod("getGenericFuture");
        Type[] returnTypes = ReflectUtils.getReturnTypes(method);

        assertNotNull(returnTypes);
        assertEquals(2, returnTypes.length);

        // First element should be Object.class (default bound of T)
        assertNotNull(returnTypes[0]);
        assertTrue(returnTypes[0] instanceof Class);
        assertEquals(Object.class, returnTypes[0]);

        // Second element should be the TypeVariable representing T
        assertNotNull(returnTypes[1]);
        assertTrue(returnTypes[1] instanceof TypeVariable);

        TypeVariable<?> typeVar = (TypeVariable<?>) returnTypes[1];
        assertEquals("T", typeVar.getName());
        // Check bounds - should have one bound which is Object
        assertEquals(1, typeVar.getBounds().length);
        assertEquals(Object.class, typeVar.getBounds()[0]);
    }

    @Test
    public void testGetReturnTypesWithBoundedGenericFuture() throws Exception {
        Method method = BoundedTypeClass.class.getMethod("getBoundedGenericFuture");
        Type[] returnTypes = ReflectUtils.getReturnTypes(method);

        assertNotNull(returnTypes);
        assertEquals(2, returnTypes.length);

        // First element should be Number.class (bound of T extends Number)
        assertNotNull(returnTypes[0]);
        assertTrue(returnTypes[0] instanceof Class);
        assertEquals(Number.class, returnTypes[0]);

        // Second element should be the TypeVariable representing T extends Number
        assertNotNull(returnTypes[1]);
        assertTrue(returnTypes[1] instanceof TypeVariable);

        TypeVariable<?> typeVar = (TypeVariable<?>) returnTypes[1];
        assertEquals("T", typeVar.getName());
        // Check bounds - should have one bound which is Number
        assertEquals(1, typeVar.getBounds().length);
        assertEquals(Number.class, typeVar.getBounds()[0]);
    }

    @Test
    public void testGetReturnTypesWithNonGenericFuture() throws Exception {
        Method method = NonGenericFutureClass.class.getMethod("getNonGenericFuture");
        Type[] returnTypes = ReflectUtils.getReturnTypes(method);

        assertNotNull(returnTypes);
        assertEquals(2, returnTypes.length);

        // First element should be String.class
        assertNotNull(returnTypes[0]);
        assertTrue(returnTypes[0] instanceof Class);
        assertEquals(String.class, returnTypes[0]);

        // Second element should be String.class (non-generic type)
        assertNotNull(returnTypes[1]);
        assertEquals(String.class, returnTypes[1]);
    }

    @Test
    public void testGetReturnTypesWithRawFuture() throws Exception {
        Method method = RawFutureClass.class.getMethod("getRawFuture");
        Type[] returnTypes = ReflectUtils.getReturnTypes(method);

        assertNotNull(returnTypes);
        assertEquals(2, returnTypes.length);

        // For raw Future, both elements should be null
        assertNull(returnTypes[0]);
        assertNull(returnTypes[1]);
    }

    @Test
    public void testGetReturnTypesWithNonFuture() throws Exception {
        Method method = NonFutureClass.class.getMethod("getNonFuture");
        Type[] returnTypes = ReflectUtils.getReturnTypes(method);

        assertNotNull(returnTypes);
        assertEquals(2, returnTypes.length);

        // First element should be String.class
        assertNotNull(returnTypes[0]);
        assertTrue(returnTypes[0] instanceof Class);
        assertEquals(String.class, returnTypes[0]);

        // Second element should be String.class
        assertNotNull(returnTypes[1]);
        assertEquals(String.class, returnTypes[1]);
    }

    @Test
    public void testGetReturnTypesWithParameterizedTypeInFuture() throws Exception {
        Method method = ParameterizedFutureClass.class.getMethod("getParameterizedFuture");
        Type[] returnTypes = ReflectUtils.getReturnTypes(method);

        assertNotNull(returnTypes);
        assertEquals(2, returnTypes.length);

        // First element should be List.class
        assertNotNull(returnTypes[0]);
        assertTrue(returnTypes[0] instanceof Class);
        assertEquals(java.util.List.class, returnTypes[0]);

        // Second element should be ParameterizedType List<String>
        assertNotNull(returnTypes[1]);
        assertTrue(returnTypes[1] instanceof ParameterizedType);

        ParameterizedType paramType = (ParameterizedType) returnTypes[1];
        assertEquals(java.util.List.class, paramType.getRawType());
        assertEquals(1, paramType.getActualTypeArguments().length);
        assertEquals(String.class, paramType.getActualTypeArguments()[0]);
    }
}

